const summary = $input.item.json;
const replyToken = $('LINE Webhook').item.json.body.events[0].replyToken;
const items = summary.items || [];
const count = items.length;
const now = new Date();
const opts = { timeZone: 'Asia/Bangkok', day: '2-digit', month: '2-digit', year: 'numeric' };
const fmtD = d => d.toLocaleDateString('th-TH', opts);
const tomorrow = new Date(now);
tomorrow.setDate(tomorrow.getDate() + 1);
const endDay = new Date(tomorrow);
endDay.setDate(endDay.getDate() + 3);
const rangeStr = fmtD(tomorrow) + ' – ' + fmtD(endDay);
const groups = {};
const order = [];
items.forEach(item => {
  if (!groups[item.date]) { groups[item.date] = []; order.push(item.date); }
  groups[item.date].push(item);
});
function kvRow(label, value) {
  return { type: 'box', layout: 'horizontal', margin: 'sm', contents: [{ type: 'text', text: label, size: 'xs', color: '#888888', flex: 3 }, { type: 'text', text: value || '-', size: 'xs', color: '#333333', flex: 5, wrap: true }] };
}
if (count === 0) {
  const flexMsg = { type: 'flex', altText: 'สรุปการจอง: ไม่มีรายการ', contents: { type: 'bubble', header: { type: 'box', layout: 'vertical', contents: [{ type: 'text', text: 'สรุปการจอง', size: 'lg', weight: 'bold', color: '#ffffff' }, { type: 'text', text: rangeStr, size: 'sm', color: '#ffffffaa' }], backgroundColor: '#1565c0', paddingAll: '16px' }, body: { type: 'box', layout: 'vertical', contents: [{ type: 'text', text: 'ไม่มีรายการจองในช่วงนี้', size: 'sm', align: 'center', color: '#888888' }], paddingAll: '16px' } } };
  return [{ json: { replyToken, flexMsg } }];
}
const bubbles = [];
const summaryRows = [{ type: 'box', layout: 'horizontal', contents: [{ type: 'text', text: 'รวมทั้งหมด', size: 'sm', color: '#555555', flex: 3 }, { type: 'text', text: count + ' รายการ', size: 'sm', weight: 'bold', color: '#1565c0', align: 'end', flex: 2 }] }, { type: 'separator', margin: 'md' }, ...order.map(dateStr => ({ type: 'box', layout: 'horizontal', margin: 'sm', contents: [{ type: 'text', text: dateStr, size: 'xs', color: '#555555', flex: 4 }, { type: 'text', text: groups[dateStr].length + ' รายการ', size: 'xs', color: '#333333', align: 'end', flex: 2 }] }))];
bubbles.push({ type: 'bubble', size: 'kilo', header: { type: 'box', layout: 'vertical', contents: [{ type: 'text', text: 'สรุปการจอง', size: 'lg', weight: 'bold', color: '#ffffff' }, { type: 'text', text: rangeStr, size: 'sm', color: '#ffffffaa' }], backgroundColor: '#1565c0', paddingAll: '16px' }, body: { type: 'box', layout: 'vertical', contents: summaryRows, paddingAll: '16px' } });
order.forEach(dateStr => {
  const dayItems = groups[dateStr];
  const bodyContents = [];
  dayItems.forEach((item, i) => {
    if (i > 0) bodyContents.push({ type: 'separator', margin: 'lg' });
    bodyContents.push({ type: 'text', text: (i + 1) + '.  ' + item.name, weight: 'bold', size: 'sm', wrap: true, color: '#1a1a1a' });
    bodyContents.push({ type: 'separator', margin: 'sm', color: '#eeeeee' });
    if (item.cartype) bodyContents.push(kvRow('ประเภทรถ', item.cartype));
    const prodStr = [item.product, item.amount].filter(Boolean).join(' ');
    if (prodStr) bodyContents.push(kvRow('สินค้า', prodStr));
    if (item.timeSlot) bodyContents.push(kvRow('เวลา', item.timeSlot));
    if (item.location) bodyContents.push(kvRow('สถานที่', item.location));
    bodyContents.push(kvRow('ผู้รับเรื่อง', (item.adminName || '-') + ' / ' + (item.transportCompany || '-')));
  });
  bubbles.push({ type: 'bubble', size: 'kilo', header: { type: 'box', layout: 'vertical', contents: [{ type: 'text', text: dateStr, size: 'md', weight: 'bold', color: '#ffffff' }, { type: 'text', text: dayItems.length + ' รายการ', size: 'xs', color: '#ffffffaa' }], backgroundColor: '#37474f', paddingAll: '12px' }, body: { type: 'box', layout: 'vertical', contents: bodyContents, paddingAll: '14px' } });
});
const flexMsg = { type: 'flex', altText: 'สรุปการจอง · ' + count + ' รายการ (' + rangeStr + ')', contents: { type: 'carousel', contents: bubbles } };
return [{ json: { replyToken, flexMsg } }];
